create table if not exists public.reels (id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id) on delete cascade,video_url text not null,caption text not null default '' check(char_length(caption)<=4000),duration_ms bigint not null default 0 check(duration_ms between 1 and 600000),width integer,height integer,view_count bigint not null default 0,like_count bigint not null default 0,share_count bigint not null default 0,comment_count bigint not null default 0,completion_count bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create index if not exists reels_created_idx on public.reels(created_at desc); create index if not exists reels_author_idx on public.reels(author_id,created_at desc); create table if not exists public.reel_sounds (reel_id uuid primary key references public.reels(id) on delete cascade,source text not null check(source in('original','licensed','spotify_reference')),title text not null default '',artist text not null default '',spotify_track_id text,spotify_uri text,spotify_url text,audio_asset_url text,created_at timestamptz not null default now(),check(source<>'spotify_reference' or(spotify_track_id is not null and audio_asset_url is null))); create table if not exists public.reel_events (id uuid primary key default gen_random_uuid(),reel_id uuid not null references public.reels(id) on delete cascade,user_id uuid references public.profiles(id) on delete set null,event_type text not null check(event_type in('impression','view_start','watch','complete','like','share','comment','save','follow_creator','skip','not_interested')),watch_ms bigint not null default 0 check(watch_ms>=0),session_id uuid,created_at timestamptz not null default now()); create index if not exists reel_events_reel_idx on public.reel_events(reel_id,created_at desc); create index if not exists reel_events_user_idx on public.reel_events(user_id,created_at desc); create table if not exists public.content_events (id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,post_id uuid references public.posts(id) on delete cascade,event_type text not null check(event_type in('impression','open','like','reply','repost','share','save','follow','hide','not_interested')),dwell_ms bigint not null default 0 check(dwell_ms>=0),created_at timestamptz not null default now(),check(post_id is not null)); create index if not exists content_events_user_idx on public.content_events(user_id,created_at desc); create table if not exists public.recommendation_feedback (user_id uuid not null references public.profiles(id) on delete cascade,topic text not null,action text not null check(action in('boost','reduce','mute')),weight numeric(8,3) not null default 1,updated_at timestamptz not null default now(),primary key(user_id,topic)); create table if not exists public.creator_programs (user_id uuid primary key references public.profiles(id) on delete cascade,enabled boolean not null default false,ads_share_bps integer not null default 0 check(ads_share_bps between 0 and 10000),subscriptions_enabled boolean not null default true,tips_enabled boolean not null default true,shopping_enabled boolean not null default false,minimum_payout_cents bigint not null default 1000 check(minimum_payout_cents>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create table if not exists public.payout_requests (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,amount_cents bigint not null check(amount_cents>0),currency text not null default 'USD',provider text,provider_ref text,status text not null default 'requested' check(status in('requested','processing','paid','failed','cancelled')),created_at timestamptz not null default now(),processed_at timestamptz); create index if not exists payout_requests_user_idx on public.payout_requests(user_id,created_at desc); alter table public.reels enable row level security; alter table public.reel_sounds enable row level security; alter table public.reel_events enable row level security; alter table public.content_events enable row level security; alter table public.recommendation_feedback enable row level security; alter table public.creator_programs enable row level security; alter table public.payout_requests enable row level security; create policy reels_read on public.reels for select to authenticated using(true); create policy reels_write_own on public.reels for all to authenticated using(author_id=auth.uid()) with check(author_id=auth.uid()); create policy reel_sounds_read on public.reel_sounds for select to authenticated using(true); create policy reel_sounds_write on public.reel_sounds for all to authenticated using(exists(select 1 from public.reels r where r.id=reel_id and r.author_id=auth.uid())) with check(exists(select 1 from public.reels r where r.id=reel_id and r.author_id=auth.uid())); create policy reel_events_own on public.reel_events for insert to authenticated with check(user_id=auth.uid()); create policy reel_events_read_own on public.reel_events for select to authenticated using(user_id=auth.uid()); create policy content_events_own on public.content_events for insert to authenticated with check(user_id=auth.uid()); create policy content_events_read_own on public.content_events for select to authenticated using(user_id=auth.uid()); create policy recommendation_feedback_own on public.recommendation_feedback for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy creator_program_read_own on public.creator_programs for select to authenticated using(user_id=auth.uid()); create policy creator_program_write_own on public.creator_programs for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy payout_requests_own on public.payout_requests for select to authenticated using(user_id=auth.uid()); create policy payout_requests_insert_own on public.payout_requests for insert to authenticated with check(user_id=auth.uid()); create or replace function public.rank_reel_score(p_reel_id uuid,p_user_id uuid,p_created_at timestamptz,p_like_count bigint,p_share_count bigint,p_comment_count bigint,p_completion_count bigint) returns numeric language sql stable security definer set search_path=public as $$ select(greatest(0,1.0-extract(epoch from(now()-p_created_at))/604800.0)*3.0)+ln(1+greatest(0,p_like_count))*1.2+ln(1+greatest(0,p_share_count))*2.2+ln(1+greatest(0,p_comment_count))*1.4+ln(1+greatest(0,p_completion_count))*1.8+case when exists(select 1 from public.reel_events e where e.reel_id=p_reel_id and e.user_id=p_user_id and e.event_type in('like','complete','save')) then 5 else 0 end+case when exists(select 1 from public.follows f join public.reels r on r.author_id=f.following_id where r.id=p_reel_id and f.follower_id=p_user_id) then 4 else 0 end; $$; revoke all on function public.rank_reel_score(uuid,uuid,timestamptz,bigint,bigint,bigint,bigint) from public; grant execute on function public.rank_reel_score(uuid,uuid,timestamptz,bigint,bigint,bigint,bigint) to authenticated; create or replace function public.get_personalized_reels(p_limit integer default 12,p_offset integer default 0) returns table(id uuid,author_id uuid,video_url text,caption text,duration_ms bigint,like_count bigint,share_count bigint,comment_count bigint,score numeric,author_username text,author_display_name text,author_avatar_url text) language sql stable security definer set search_path=public as $$ with candidates as(select r.*,p.username,p.display_name,p.avatar_url,(greatest(0,1.0-extract(epoch from(now()-r.created_at))/604800.0)*3.0)+ln(1+r.like_count)*1.2+ln(1+r.share_count)*2.2+ln(1+r.comment_count)*1.4+ln(1+r.completion_count)*1.8+case when exists(select 1 from public.follows f where f.follower_id=auth.uid() and f.following_id=r.author_id) then 4 else 0 end+case when exists(select 1 from public.reel_events e where e.user_id=auth.uid() and e.reel_id=r.id and e.event_type in('like','complete','save')) then 5 else 0 end-case when exists(select 1 from public.reel_events e where e.user_id=auth.uid() and e.reel_id=r.id and e.event_type in('not_interested','skip')) then 8 else 0 end s from public.reels r join public.profiles p on p.id=r.author_id where r.duration_ms>0),diverse as(select c.*,row_number() over(partition by c.author_id order by c.s desc,c.created_at desc) author_rank from candidates c) select id,author_id,video_url,caption,duration_ms,like_count,share_count,comment_count,s,username,display_name,avatar_url from diverse where author_rank<=3 order by s desc,created_at desc limit least(greatest(p_limit,1),30) offset greatest(p_offset,0); $$; revoke all on function public.get_personalized_reels(integer,integer) from public; grant execute on function public.get_personalized_reels(integer,integer) to authenticated;;
